// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(mintAmount > 0);
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= mintAmount);

        c.mintToken(address(this), mintAmount);

        c.burn(burnAmount);

        uint256 sumBalances = c.balanceOf(address(this));

        assertTrue(c.totalSupply() == sumBalances);
    }
}
